 20→// stalenessThreshold is the duration after which an active session is considered stuck.
 21→const stalenessThreshold = 1 * time.Hour
 22→
 23→func newDoctorCmd() *cobra.Command {
 24→	var forceFlag bool
 25→
 26→	cmd := &cobra.Command{
 27→		Use:   "doctor",
 28→		Short: "Fix stuck sessions",
 29→		Long: `Scan for stuck or problematic sessions and offer to fix them.
 30→
 31→A session is considered stuck if:
 32→  - It is in ACTIVE phase with no interaction for over 1 hour
 33→  - It is in ENDED phase with uncondensed checkpoint data on a shadow branch
 34→
 35→For each stuck session, you can choose to:
 36→  - Condense: Save session data to permanent storage (entire/checkpoints/v1 branch)
 37→  - Discard: Remove the session state and shadow branch data
 38→  - Skip: Leave the session as-is
 39→
 40→Use --force to condense all fixable sessions without prompting.  Sessions that can't
 41→be condensed will be discarded.`,
 42→		RunE: func(cmd *cobra.Command, _ []string) error {
 43→			return runSessionsFix(cmd, forceFlag)
 44→		},
 45→	}
 46→
 47→	cmd.Flags().BoolVarP(&forceFlag, "force", "f", false, "Fix all stuck sessions without prompting (condense if possible, otherwise discard)")
 48→
 49→	return cmd
 50→}
