 52→// stuckSession holds a session state along with diagnostic info.
 53→type stuckSession struct {
 54→	State             *strategy.SessionState
 55→	Reason            string
 56→	ShadowBranch      string
 57→	HasShadowBranch   bool
 58→	CheckpointCount   int
 59→	FilesTouchedCount int
 60→}
 61→
 62→func runSessionsFix(cmd *cobra.Command, force bool) error {
 63→	ctx := cmd.Context()
 64→	// Load all session states
 65→	states, err := strategy.ListSessionStates(ctx)
 66→	if err != nil {
 67→		return fmt.Errorf("failed to list session states: %w", err)
 68→	}
 69→
 70→	if len(states) == 0 {
 71→		fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
 72→		return nil
 73→	}
 74→
 75→	// Open repository to check shadow branches (uses worktree-aware helper)
 76→	repo, err := openRepository(ctx)
 77→	if err != nil {
 78→		return fmt.Errorf("failed to open repository: %w", err)
 79→	}
 80→
 81→	// Identify stuck sessions
 82→	now := time.Now()
 83→	var stuck []stuckSession
 84→
 85→	for _, state := range states {
 86→		ss := classifySession(state, repo, now)
 87→		if ss != nil {
 88→			stuck = append(stuck, *ss)
 89→		}
 90→	}
 91→
 92→	if len(stuck) == 0 {
 93→		fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
 94→		return nil
 95→	}
 96→
 97→	// Get the current strategy for condense operations
 98→	strat := GetStrategy(ctx)
 99→
100→	fmt.Fprintf(cmd.OutOrStdout(), "Found %d stuck session(s):\n\n", len(stuck))
101→
102→	for _, ss := range stuck {
103→		displayStuckSession(cmd, ss)
104→
105→		if force {
106→			if ss.HasShadowBranch && ss.CheckpointCount > 0 {
107→				if err := strat.CondenseSessionByID(ctx, ss.State.SessionID); err != nil {
108→					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
109→				} else {
110→					fmt.Fprintf(cmd.OutOrStdout(), "  -> Condensed session %s\n\n", ss.State.SessionID)
111→				}
112→			} else {
113→				// Discard if we can't condense
114→				if err := discardSession(ctx, ss, repo, cmd.ErrOrStderr()); err != nil {
115→					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
116→				} else {
117→					fmt.Fprintf(cmd.OutOrStdout(), "  -> Discarded session %s\n\n", ss.State.SessionID)
118→				}
119→			}
120→			continue
121→		}
122→
123→		// Interactive: prompt for action
124→		action, err := promptSessionAction(ss)
125→		if err != nil {
126→			if errors.Is(err, huh.ErrUserAborted) {
127→				return nil
128→			}
129→			return fmt.Errorf("failed to get action: %w", err)
130→		}
131→
132→		switch action {
133→		case "condense":
134→			if err := strat.CondenseSessionByID(ctx, ss.State.SessionID); err != nil {
135→				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
136→			} else {
137→				fmt.Fprintf(cmd.OutOrStdout(), "  -> Condensed session %s\n\n", ss.State.SessionID)
138→			}
139→		case "discard":
140→			if err := discardSession(ctx, ss, repo, cmd.ErrOrStderr()); err != nil {
141→				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
142→			} else {
143→				fmt.Fprintf(cmd.OutOrStdout(), "  -> Discarded session %s\n\n", ss.State.SessionID)
144→			}
145→		case "skip":
146→			fmt.Fprintf(cmd.OutOrStdout(), "  -> Skipped\n\n")
147→		}
148→	}
149→
150→	return nil
151→}
