153→// classifySession determines if a session is stuck and returns diagnostic info.
154→// Returns nil if the session is healthy.
155→func classifySession(state *strategy.SessionState, repo *git.Repository, now time.Time) *stuckSession {
156→	// Determine shadow branch info
157→	shadowBranch := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
158→	refName := plumbing.NewBranchReferenceName(shadowBranch)
159→	_, refErr := repo.Reference(refName, true)
160→	hasShadowBranch := refErr == nil
161→
162→	switch {
163→	case state.Phase.IsActive():
164→		// Active sessions are stuck if no interaction for over the staleness threshold
165→		isStale := state.LastInteractionTime == nil || now.Sub(*state.LastInteractionTime) > stalenessThreshold
166→		if !isStale {
167→			return nil
168→		}
169→
170→		var reason string
171→		if state.LastInteractionTime != nil {
172→			reason = fmt.Sprintf("active, last interaction %s ago", now.Sub(*state.LastInteractionTime).Truncate(time.Minute))
173→		} else {
174→			reason = "active, no recorded interaction time"
175→		}
176→
177→		return &stuckSession{
178→			State:             state,
179→			Reason:            reason,
180→			ShadowBranch:      shadowBranch,
181→			HasShadowBranch:   hasShadowBranch,
182→			CheckpointCount:   state.StepCount,
183→			FilesTouchedCount: len(state.FilesTouched),
184→		}
185→
186→	case state.Phase == session.PhaseEnded:
187→		// Ended sessions are stuck if they have uncondensed data
188→		if state.StepCount <= 0 || !hasShadowBranch {
189→			return nil
190→		}
191→
192→		return &stuckSession{
193→			State:             state,
194→			Reason:            "ended with uncondensed checkpoint data",
195→			ShadowBranch:      shadowBranch,
196→			HasShadowBranch:   hasShadowBranch,
197→			CheckpointCount:   state.StepCount,
198→			FilesTouchedCount: len(state.FilesTouched),
199→		}
200→
201→	default:
202→		return nil
203→	}
204→}
