206→// displayStuckSession prints diagnostic info for a stuck session.
207→func displayStuckSession(cmd *cobra.Command, ss stuckSession) {
208→	w := cmd.OutOrStdout()
209→
210→	fmt.Fprintf(w, "  Session: %s\n", ss.State.SessionID)
211→	fmt.Fprintf(w, "  Phase:   %s\n", ss.State.Phase)
212→	fmt.Fprintf(w, "  Reason:  %s\n", ss.Reason)
213→
214→	if ss.State.AgentType != "" {
215→		fmt.Fprintf(w, "  Agent:   %s\n", ss.State.AgentType)
216→	}
217→
218→	if ss.State.LastInteractionTime != nil {
219→		fmt.Fprintf(w, "  Last interaction: %s\n", ss.State.LastInteractionTime.Format(time.RFC3339))
220→	}
221→
222→	shadowStatus := "not found"
223→	if ss.HasShadowBranch {
224→		shadowStatus = fmt.Sprintf("exists (%s)", ss.ShadowBranch)
225→	}
226→	fmt.Fprintf(w, "  Shadow branch: %s\n", shadowStatus)
227→	fmt.Fprintf(w, "  Checkpoints: %d, Files touched: %d\n", ss.CheckpointCount, ss.FilesTouchedCount)
228→}
