230→// promptSessionAction asks the user what to do with a stuck session.
231→func promptSessionAction(ss stuckSession) (string, error) {
232→	var action string
233→
234→	options := make([]huh.Option[string], 0, 3)
235→	if ss.HasShadowBranch && ss.CheckpointCount > 0 {
236→		options = append(options, huh.NewOption("Condense (save to permanent storage)", "condense"))
237→	}
238→	options = append(options,
239→		huh.NewOption("Discard (remove session data)", "discard"),
240→		huh.NewOption("Skip (leave as-is)", "skip"),
241→	)
242→
243→	form := NewAccessibleForm(
244→		huh.NewGroup(
245→			huh.NewSelect[string]().
246→				Title(fmt.Sprintf("Fix session %s?", ss.State.SessionID)).
247→				Options(options...).
248→				Value(&action),
249→		),
250→	)
251→
252→	if err := form.Run(); err != nil {
253→		return "", fmt.Errorf("session fix prompt failed: %w", err)
254→	}
255→
256→	return action, nil
257→}
