283→// canDeleteShadowBranch checks if a shadow branch can be safely deleted.
284→// Returns true if no other sessions (besides excludeSessionID) need this branch.
285→func canDeleteShadowBranch(ctx context.Context, shadowBranch, excludeSessionID string) (bool, error) {
286→	states, err := strategy.ListSessionStates(ctx)
287→	if err != nil {
288→		return false, fmt.Errorf("failed to list session states: %w", err)
289→	}
290→
291→	for _, state := range states {
292→		if state.SessionID == excludeSessionID {
293→			continue
294→		}
295→		otherShadow := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
296→		if otherShadow == shadowBranch && state.StepCount > 0 {
297→			return false, nil
298→		}
299→	}
300→
301→	return true, nil
302→}
