 19→// ReconcileDisconnectedMetadataBranch detects and repairs disconnected local/remote
 20→// entire/checkpoints/v1 branches. Disconnected means no common ancestor, which
 21→// only happens due to the empty-orphan bug. Diverged (shared ancestor) is normal
 22→// and handled by the push path's tree merge.
 23→//
 24→// Repair strategy: cherry-pick local commits onto remote tip, preserving all data.
 25→// Checkpoint shards use unique paths (<id[:2]>/<id[2:]>/), so cherry-picks always
 26→// apply cleanly.
 27→func ReconcileDisconnectedMetadataBranch(repo *git.Repository) error {
 28→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
 29→
 30→	// Check local branch
 31→	localRef, err := repo.Reference(refName, true)
 32→	if errors.Is(err, plumbing.ErrReferenceNotFound) {
 33→		return nil // No local branch — nothing to reconcile
 34→	}
 35→	if err != nil {
 36→		return fmt.Errorf("failed to check local metadata branch: %w", err)
 37→	}
 38→
 39→	// Check remote-tracking branch
 40→	remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
 41→	remoteRef, err := repo.Reference(remoteRefName, true)
 42→	if errors.Is(err, plumbing.ErrReferenceNotFound) {
 43→		return nil // No remote branch — nothing to reconcile
 44→	}
 45→	if err != nil {
 46→		return fmt.Errorf("failed to check remote metadata branch: %w", err)
 47→	}
 48→
 49→	localHash := localRef.Hash()
 50→	remoteHash := remoteRef.Hash()
 51→
 52→	// Same hash — nothing to do
 53→	if localHash == remoteHash {
 54→		return nil
 55→	}
 56→
 57→	// Check if disconnected using git merge-base
 58→	repoPath, err := getRepoPath(repo)
 59→	if err != nil {
 60→		return err
 61→	}
 62→
 63→	disconnected, err := isDisconnected(repoPath, localHash.String(), remoteHash.String())
 64→	if err != nil {
 65→		return fmt.Errorf("failed to check metadata branch ancestry: %w", err)
 66→	}
 67→	if !disconnected {
 68→		// Shared ancestry (diverged or ancestor) — not our problem
 69→		return nil
 70→	}
 71→
 72→	// Disconnected — cherry-pick local commits onto remote tip
 73→	fmt.Fprintln(os.Stderr, "[entire] Detected disconnected session metadata (local and remote share no common ancestor)")
 74→
 75→	// Collect local commits oldest-first
 76→	localCommits, err := collectCommitChain(repo, localHash)
 77→	if err != nil {
 78→		return fmt.Errorf("failed to collect local commits: %w", err)
 79→	}
 80→
 81→	// Filter out empty-tree commits (the orphan bug commit)
 82→	var dataCommits []*object.Commit
 83→	for _, c := range localCommits {
 84→		tree, treeErr := c.Tree()
 85→		if treeErr != nil {
 86→			return fmt.Errorf("failed to read tree for commit %s: %w", c.Hash.String()[:7], treeErr)
 87→		}
 88→		if len(tree.Entries) > 0 {
 89→			dataCommits = append(dataCommits, c)
 90→		}
 91→	}
 92→
 93→	if len(dataCommits) == 0 {
 94→		// Local only had empty orphan — just point to remote
 95→		ref := plumbing.NewHashReference(refName, remoteHash)
 96→		if err := repo.Storer.SetReference(ref); err != nil {
 97→			return fmt.Errorf("failed to reset metadata branch to remote: %w", err)
 98→		}
 99→		fmt.Fprintln(os.Stderr, "[entire] Done — local had no checkpoint data, reset to remote")
100→		return nil
101→	}
102→
103→	fmt.Fprintf(os.Stderr, "[entire] Cherry-picking %d local checkpoint(s) onto remote...\n", len(dataCommits))
104→
105→	newTip, err := cherryPickOnto(repo, remoteHash, dataCommits)
106→	if err != nil {
107→		return fmt.Errorf("failed to cherry-pick local commits onto remote: %w", err)
108→	}
109→
110→	// Update local branch ref
111→	ref := plumbing.NewHashReference(refName, newTip)
112→	if err := repo.Storer.SetReference(ref); err != nil {
113→		return fmt.Errorf("failed to update metadata branch: %w", err)
114→	}
115→
116→	fmt.Fprintln(os.Stderr, "[entire] Done — all local and remote checkpoints preserved")
117→	return nil
118→}
