120→// isDisconnected checks if two commits have no common ancestor using git merge-base.
121→// Returns (true, nil) if disconnected, (false, nil) if they share ancestry,
122→// or (false, error) if git merge-base failed for another reason.
123→//
124→// git merge-base exit codes:
125→//   - 0: common ancestor found (shared ancestry)
126→//   - 1: no common ancestor (disconnected)
127→//   - 128+: error (corrupt repo, invalid hash, etc.)
128→func isDisconnected(repoPath, hashA, hashB string) (bool, error) {
129→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
130→	defer cancel()
131→	cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
132→	cmd.Dir = repoPath
133→	if err := cmd.Run(); err != nil {
134→		var exitErr *exec.ExitError
135→		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
136→			return true, nil // No common ancestor — disconnected
137→		}
138→		return false, fmt.Errorf("git merge-base failed: %w", err)
139→	}
140→	return false, nil // Shared ancestry
141→}
