143→// collectCommitChain walks from tip to root following first parent, returns oldest-first.
144→func collectCommitChain(repo *git.Repository, tip plumbing.Hash) ([]*object.Commit, error) {
145→	var chain []*object.Commit
146→	current := tip
147→
148→	reachedRoot := false
149→	for range MaxCommitTraversalDepth {
150→		commit, err := repo.CommitObject(current)
151→		if err != nil {
152→			return nil, fmt.Errorf("failed to get commit %s: %w", current, err)
153→		}
154→		chain = append(chain, commit)
155→
156→		if len(commit.ParentHashes) == 0 {
157→			reachedRoot = true
158→			break
159→		}
160→		current = commit.ParentHashes[0]
161→	}
162→
163→	if !reachedRoot {
164→		return nil, fmt.Errorf("commit chain exceeded %d commits without reaching root; aborting reconciliation", MaxCommitTraversalDepth)
165→	}
166→
167→	// Reverse to oldest-first
168→	for i, j := 0, len(chain)-1; i < j; i, j = i+1, j-1 {
169→		chain[i], chain[j] = chain[j], chain[i]
170→	}
171→
172→	return chain, nil
173→}
