175→// cherryPickOnto applies each commit's delta onto base, building a linear chain.
176→// For each commit, it computes the full diff from its parent (additions, modifications,
177→// and deletions), then applies that delta onto the current tip's tree.
178→func cherryPickOnto(repo *git.Repository, base plumbing.Hash, commits []*object.Commit) (plumbing.Hash, error) {
179→	currentTip := base
180→
181→	for _, commit := range commits {
182→		// Get the commit's tree entries
183→		commitTree, err := commit.Tree()
184→		if err != nil {
185→			return plumbing.ZeroHash, fmt.Errorf("failed to get tree for commit %s: %w", commit.Hash, err)
186→		}
187→
188→		commitEntries := make(map[string]object.TreeEntry)
189→		if err := checkpoint.FlattenTree(repo, commitTree, "", commitEntries); err != nil {
190→			return plumbing.ZeroHash, fmt.Errorf("failed to flatten commit tree: %w", err)
191→		}
192→
193→		// Get parent's tree entries (empty if root commit)
194→		parentEntries := make(map[string]object.TreeEntry)
195→		if len(commit.ParentHashes) > 0 {
196→			parentCommit, pErr := repo.CommitObject(commit.ParentHashes[0])
197→			if pErr != nil {
198→				return plumbing.ZeroHash, fmt.Errorf("failed to get parent commit %s: %w", commit.ParentHashes[0], pErr)
199→			}
200→			parentTree, ptErr := parentCommit.Tree()
201→			if ptErr != nil {
202→				return plumbing.ZeroHash, fmt.Errorf("failed to get parent tree for commit %s: %w", commit.ParentHashes[0], ptErr)
203→			}
204→			if err := checkpoint.FlattenTree(repo, parentTree, "", parentEntries); err != nil {
205→				return plumbing.ZeroHash, fmt.Errorf("failed to flatten parent tree for commit %s: %w", commit.ParentHashes[0], err)
206→			}
207→		}
208→
209→		// Compute full delta: additions, modifications, and deletions
210→		added := make(map[string]object.TreeEntry)
211→		for path, entry := range commitEntries {
212→			parentEntry, exists := parentEntries[path]
213→			if !exists || parentEntry.Hash != entry.Hash {
214→				added[path] = entry // New or modified
215→			}
216→		}
217→		var deleted []string
218→		for path := range parentEntries {
219→			if _, exists := commitEntries[path]; !exists {
220→				deleted = append(deleted, path) // Removed in this commit
221→			}
222→		}
223→
224→		if len(added) == 0 && len(deleted) == 0 {
225→			continue // Skip no-op commits
226→		}
227→
228→		// Get current tip's tree and apply delta
229→		tipCommit, err := repo.CommitObject(currentTip)
230→		if err != nil {
231→			return plumbing.ZeroHash, fmt.Errorf("failed to get tip commit: %w", err)
232→		}
233→		tipTree, err := tipCommit.Tree()
234→		if err != nil {
235→			return plumbing.ZeroHash, fmt.Errorf("failed to get tip tree: %w", err)
236→		}
237→
238→		mergedEntries := make(map[string]object.TreeEntry)
239→		if err := checkpoint.FlattenTree(repo, tipTree, "", mergedEntries); err != nil {
240→			return plumbing.ZeroHash, fmt.Errorf("failed to flatten tip tree: %w", err)
241→		}
242→		for path, entry := range added {
243→			mergedEntries[path] = entry
244→		}
245→		for _, path := range deleted {
246→			delete(mergedEntries, path)
247→		}
248→
249→		mergedTreeHash, err := checkpoint.BuildTreeFromEntries(repo, mergedEntries)
250→		if err != nil {
251→			return plumbing.ZeroHash, fmt.Errorf("failed to build merged tree: %w", err)
252→		}
253→
254→		// Create new commit on top of current tip, preserving original message/author
255→		newHash, err := createCherryPickCommit(repo, mergedTreeHash, currentTip, commit)
256→		if err != nil {
257→			return plumbing.ZeroHash, fmt.Errorf("failed to create cherry-pick commit: %w", err)
258→		}
259→
260→		currentTip = newHash
261→	}
262→
263→	return currentTip, nil
264→}
265→
266→// createCherryPickCommit creates a new commit on top of parent, preserving the
267→// original commit's message and author.
268→func createCherryPickCommit(repo *git.Repository, treeHash, parent plumbing.Hash, original *object.Commit) (plumbing.Hash, error) {
269→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
270→	now := time.Now()
271→
272→	commit := &object.Commit{
273→		TreeHash:     treeHash,
274→		ParentHashes: []plumbing.Hash{parent},
275→		Author:       original.Author,
276→		Committer: object.Signature{
277→			Name:  authorName,
278→			Email: authorEmail,
279→			When:  now,
280→		},
281→		Message: original.Message,
282→	}
283→
284→	obj := repo.Storer.NewEncodedObject()
285→	if err := commit.Encode(obj); err != nil {
286→		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
287→	}
288→
289→	hash, err := repo.Storer.SetEncodedObject(obj)
290→	if err != nil {
291→		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
292→	}
293→
294→	return hash, nil
295→}
