259→// discardSession removes session state and cleans up the shadow branch.
260→func discardSession(ctx context.Context, ss stuckSession, _ *git.Repository, errW io.Writer) error {
261→	// Clear session state file
262→	if err := strategy.ClearSessionState(ctx, ss.State.SessionID); err != nil {
263→		return fmt.Errorf("failed to clear session state: %w", err)
264→	}
265→
266→	// Delete shadow branch if it exists and no other sessions need it
267→	if ss.HasShadowBranch {
268→		if shouldDelete, err := canDeleteShadowBranch(ctx, ss.ShadowBranch, ss.State.SessionID); err != nil {
269→			fmt.Fprintf(errW, "Warning: could not check other sessions for shadow branch: %v\n", err)
270→		} else if shouldDelete {
271→			if err := strategy.DeleteBranchCLI(ctx, ss.ShadowBranch); err != nil {
272→				// Branch already gone is not an error — keeps discard idempotent
273→				if !errors.Is(err, strategy.ErrBranchNotFound) {
274→					return fmt.Errorf("failed to delete shadow branch: %w", err)
275→				}
276→			}
277→		}
278→	}
279→
280→	return nil
281→}
