 29→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
 30→	localRef, err := repo.Reference(refName, true)
 31→	if errors.Is(err, plumbing.ErrReferenceNotFound) {
 32→		return false, nil
 33→	}
 34→	if err != nil {
 35→		return false, fmt.Errorf("failed to check local metadata branch: %w", err)
 36→	}
 37→
 38→	remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
 39→	remoteRef, err := repo.Reference(remoteRefName, true)
 40→	if errors.Is(err, plumbing.ErrReferenceNotFound) {
 41→		return false, nil
 42→	}
 43→	if err != nil {
 44→		return false, fmt.Errorf("failed to check remote metadata branch: %w", err)
 45→	}
 46→
 47→	if localRef.Hash() == remoteRef.Hash() {
 48→		return false, nil
 49→	}
 50→
 51→	repoPath, err := getRepoPath(repo)
 52→	if err != nil {
 53→		return false, err
 54→	}
 55→
 56→	return isDisconnected(repoPath, localRef.Hash().String(), remoteRef.Hash().String())
 57→}
