 77→// ReconcileDisconnectedMetadataBranch detects and repairs disconnected local/remote
 78→// entire/checkpoints/v1 branches. Disconnected means no common ancestor, which
 79→// only happens due to the empty-orphan bug. Diverged (shared ancestor) is normal
 80→// and handled by the push path's tree merge.
 81→//
 82→// Repair strategy: cherry-pick local commits onto remote tip, preserving all data.
 83→// Checkpoint shards use unique paths (<id[:2]>/<id[2:]>/), so cherry-picks always
 84→// apply cleanly.
 85→func ReconcileDisconnectedMetadataBranch(repo *git.Repository) error {
 86→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
 87→
 88→	// Check local branch
 89→	localRef, err := repo.Reference(refName, true)
 90→	if errors.Is(err, plumbing.ErrReferenceNotFound) {
 91→		return nil // No local branch — nothing to reconcile
 92→	}
 93→	if err != nil {
 94→		return fmt.Errorf("failed to check local metadata branch: %w", err)
 95→	}
 96→
 97→	// Check remote-tracking branch
 98→	remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
 99→	remoteRef, err := repo.Reference(remoteRefName, true)
100→	if errors.Is(err, plumbing.ErrReferenceNotFound) {
101→		return nil // No remote branch — nothing to reconcile
102→	}
103→	if err != nil {
104→		return fmt.Errorf("failed to check remote metadata branch: %w", err)
105→	}
106→
107→	localHash := localRef.Hash()
108→	remoteHash := remoteRef.Hash()
109→
110→	// Same hash — nothing to do
111→	if localHash == remoteHash {
112→		return nil
113→	}
114→
115→	// Check if disconnected using git merge-base
116→	repoPath, err := getRepoPath(repo)
117→	if err != nil {
118→		return err
119→	}
120→
121→	disconnected, err := isDisconnected(repoPath, localHash.String(), remoteHash.String())
122→	if err != nil {
123→		return fmt.Errorf("failed to check metadata branch ancestry: %w", err)
124→	}
125→	if !disconnected {
126→		// Shared ancestry (diverged or ancestor) — not our problem
127→		return nil
128→	}
129→
130→	// Disconnected — cherry-pick local commits onto remote tip
131→	fmt.Fprintln(os.Stderr, "[entire] Detected disconnected session metadata (local and remote share no common ancestor)")
132→
133→	// Collect local commits oldest-first
134→	localCommits, err := collectCommitChain(repo, localHash)
135→	if err != nil {
136→		return fmt.Errorf("failed to collect local commits: %w", err)
137→	}
138→
139→	// Filter out empty-tree commits (the orphan bug commit)
140→	var dataCommits []*object.Commit
141→	for _, c := range localCommits {
142→		tree, treeErr := c.Tree()
143→		if treeErr != nil {
144→			return fmt.Errorf("failed to read tree for commit %s: %w", c.Hash.String()[:7], treeErr)
145→		}
146→		if len(tree.Entries) > 0 {
147→			dataCommits = append(dataCommits, c)
148→		}
149→	}
150→
151→	if len(dataCommits) == 0 {
152→		// Local only had empty orphan — just point to remote
153→		ref := plumbing.NewHashReference(refName, remoteHash)
154→		if err := repo.Storer.SetReference(ref); err != nil {
155→			return fmt.Errorf("failed to reset metadata branch to remote: %w", err)
156→		}
157→		fmt.Fprintln(os.Stderr, "[entire] Done — local had no checkpoint data, reset to remote")
158→		return nil
159→	}
160→
161→	fmt.Fprintf(os.Stderr, "[entire] Cherry-picking %d local checkpoint(s) onto remote...\n", len(dataCommits))
162→
163→	newTip, err := cherryPickOnto(repo, remoteHash, dataCommits)
164→	if err != nil {
165→		return fmt.Errorf("failed to cherry-pick local commits onto remote: %w", err)
166→	}
167→
168→	// Update local branch ref
169→	ref := plumbing.NewHashReference(refName, newTip)
170→	if err := repo.Storer.SetReference(ref); err != nil {
171→		return fmt.Errorf("failed to update metadata branch: %w", err)
172→	}
173→
174→	fmt.Fprintln(os.Stderr, "[entire] Done — all local and remote checkpoints preserved")
175→	return nil
176→}
