178→// isDisconnected checks if two commits have no common ancestor using git merge-base.
179→// Returns (true, nil) if disconnected, (false, nil) if they share ancestry,
180→// or (false, error) if git merge-base failed for another reason.
181→//
182→// git merge-base exit codes:
183→//   - 0: common ancestor found (shared ancestry)
184→//   - 1: no common ancestor (disconnected)
185→//   - 128+: error (corrupt repo, invalid hash, etc.)
186→func isDisconnected(repoPath, hashA, hashB string) (bool, error) {
187→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
188→	defer cancel()
189→	cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
190→	cmd.Dir = repoPath
191→	if err := cmd.Run(); err != nil {
192→		var exitErr *exec.ExitError
193→		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
194→			return true, nil // No common ancestor — disconnected
195→		}
196→		return false, fmt.Errorf("git merge-base failed: %w", err)
197→	}
198→	return false, nil // Shared ancestry
199→}
