201→// collectCommitChain walks from tip to root following first parent, returns oldest-first.
202→func collectCommitChain(repo *git.Repository, tip plumbing.Hash) ([]*object.Commit, error) {
203→	var chain []*object.Commit
204→	current := tip
205→
206→	reachedRoot := false
207→	for range MaxCommitTraversalDepth {
208→		commit, err := repo.CommitObject(current)
209→		if err != nil {
210→			return nil, fmt.Errorf("failed to get commit %s: %w", current, err)
211→		}
212→		chain = append(chain, commit)
213→
214→		if len(commit.ParentHashes) == 0 {
215→			reachedRoot = true
216→			break
217→		}
218→		current = commit.ParentHashes[0]
219→	}
220→
221→	if !reachedRoot {
222→		return nil, fmt.Errorf("commit chain exceeded %d commits without reaching root; aborting reconciliation", MaxCommitTraversalDepth)
223→	}
224→
225→	// Reverse to oldest-first
226→	for i, j := 0, len(chain)-1; i < j; i, j = i+1, j-1 {
227→		chain[i], chain[j] = chain[j], chain[i]
228→	}
229→
230→	return chain, nil
231→}
