233→// cherryPickOnto applies each commit's delta onto base, building a linear chain.
234→// For each commit, it computes the full diff from its parent (additions, modifications,
235→// and deletions), then applies that delta onto the current tip's tree.
236→func cherryPickOnto(repo *git.Repository, base plumbing.Hash, commits []*object.Commit) (plumbing.Hash, error) {
237→	currentTip := base
238→
239→	for _, commit := range commits {
240→		// Get the commit's tree entries
241→		commitTree, err := commit.Tree()
242→		if err != nil {
243→			return plumbing.ZeroHash, fmt.Errorf("failed to get tree for commit %s: %w", commit.Hash, err)
244→		}
245→
246→		commitEntries := make(map[string]object.TreeEntry)
247→		if err := checkpoint.FlattenTree(repo, commitTree, "", commitEntries); err != nil {
248→			return plumbing.ZeroHash, fmt.Errorf("failed to flatten commit tree: %w", err)
249→		}
250→
251→		// Get parent's tree entries (empty if root commit)
252→		parentEntries := make(map[string]object.TreeEntry)
253→		if len(commit.ParentHashes) > 0 {
254→			parentCommit, pErr := repo.CommitObject(commit.ParentHashes[0])
255→			if pErr != nil {
256→				return plumbing.ZeroHash, fmt.Errorf("failed to get parent commit %s: %w", commit.ParentHashes[0], pErr)
257→			}
258→			parentTree, ptErr := parentCommit.Tree()
259→			if ptErr != nil {
260→				return plumbing.ZeroHash, fmt.Errorf("failed to get parent tree for commit %s: %w", commit.ParentHashes[0], ptErr)
261→			}
262→			if err := checkpoint.FlattenTree(repo, parentTree, "", parentEntries); err != nil {
263→				return plumbing.ZeroHash, fmt.Errorf("failed to flatten parent tree for commit %s: %w", commit.ParentHashes[0], err)
264→			}
265→		}
266→
267→		// Compute full delta: additions, modifications, and deletions
268→		added := make(map[string]object.TreeEntry)
269→		for path, entry := range commitEntries {
270→			parentEntry, exists := parentEntries[path]
271→			if !exists || parentEntry.Hash != entry.Hash {
272→				added[path] = entry // New or modified
273→			}
274→		}
275→		var deleted []string
276→		for path := range parentEntries {
277→			if _, exists := commitEntries[path]; !exists {
278→				deleted = append(deleted, path) // Removed in this commit
279→			}
280→		}
281→
282→		if len(added) == 0 && len(deleted) == 0 {
283→			continue // Skip no-op commits
284→		}
285→
286→		// Get current tip's tree and apply delta
287→		tipCommit, err := repo.CommitObject(currentTip)
288→		if err != nil {
289→			return plumbing.ZeroHash, fmt.Errorf("failed to get tip commit: %w", err)
290→		}
291→		tipTree, err := tipCommit.Tree()
292→		if err != nil {
293→			return plumbing.ZeroHash, fmt.Errorf("failed to get tip tree: %w", err)
294→		}
295→
296→		mergedEntries := make(map[string]object.TreeEntry)
297→		if err := checkpoint.FlattenTree(repo, tipTree, "", mergedEntries); err != nil {
298→			return plumbing.ZeroHash, fmt.Errorf("failed to flatten tip tree: %w", err)
299→		}
300→		for path, entry := range added {
301→			mergedEntries[path] = entry
302→		}
303→		for _, path := range deleted {
304→			delete(mergedEntries, path)
305→		}
306→
307→		mergedTreeHash, err := checkpoint.BuildTreeFromEntries(repo, mergedEntries)
308→		if err != nil {
309→			return plumbing.ZeroHash, fmt.Errorf("failed to build merged tree: %w", err)
310→		}
311→
312→		// Create new commit on top of current tip, preserving original message/author
313→		newHash, err := createCherryPickCommit(repo, mergedTreeHash, currentTip, commit)
314→		if err != nil {
315→			return plumbing.ZeroHash, fmt.Errorf("failed to create cherry-pick commit: %w", err)
316→		}
317→
318→		currentTip = newHash
319→	}
320→
321→	return currentTip, nil
322→}
