324→// createCherryPickCommit creates a new commit on top of parent, preserving the
325→// original commit's message and author.
326→func createCherryPickCommit(repo *git.Repository, treeHash, parent plumbing.Hash, original *object.Commit) (plumbing.Hash, error) {
327→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
328→	now := time.Now()
329→
330→	commit := &object.Commit{
331→		TreeHash:     treeHash,
332→		ParentHashes: []plumbing.Hash{parent},
333→		Author:       original.Author,
334→		Committer: object.Signature{
335→			Name:  authorName,
336→			Email: authorEmail,
337→			When:  now,
338→		},
339→		Message: original.Message,
340→	}
341→
342→	obj := repo.Storer.NewEncodedObject()
343→	if err := commit.Encode(obj); err != nil {
344→		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
345→	}
346→
347→	hash, err := repo.Storer.SetEncodedObject(obj)
348→	if err != nil {
349→		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
350→	}
351→
352→	return hash, nil
353→}
