356→func getRepoPath(repo *git.Repository) (string, error) {
357→	wt, err := repo.Worktree()
358→	if err != nil {
359→		return "", fmt.Errorf("failed to get worktree: %w", err)
360→	}
361→	return wt.Filesystem.Root(), nil
